package com.bank.savings.service;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Finds all combinations of deposit denominations that reach a goal (with reuse).
public class CombinationSumService {
    private static final Logger log = Logger.getLogger(CombinationSumService.class.getName());

    public List<List<BigDecimal>> combinationsToGoal(List<BigDecimal> denominations,
                                                     BigDecimal goal) {
        // Sort so we can prune when a denomination exceeds the remaining goal.
        List<BigDecimal> sorted = new ArrayList<>(denominations);
        sorted.sort(BigDecimal::compareTo);
        List<List<BigDecimal>> result = new ArrayList<>();
        backtrack(sorted, goal, 0, new ArrayList<>(), result);
        log.info(() -> "Found " + result.size() + " deposit combinations");
        return result;
    }

    private void backtrack(List<BigDecimal> denoms, BigDecimal remaining, int start,
                           List<BigDecimal> current, List<List<BigDecimal>> result) {
        if (remaining.compareTo(BigDecimal.ZERO) == 0) {
            result.add(new ArrayList<>(current)); // exact hit: record a copy
            log.fine(() -> "Goal reached with " + current);
            return;
        }
        for (int i = start; i < denoms.size(); i++) {
            BigDecimal d = denoms.get(i);
            if (d.compareTo(remaining) > 0) {
                break; // sorted: no later denomination fits either
            }
            current.add(d);
            // Pass i (not i+1) to allow reusing this denomination.
            backtrack(denoms, remaining.subtract(d), i, current, result);
            current.remove(current.size() - 1); // backtrack
        }
    }
}
