package com.bank.savings;

import com.bank.savings.service.CombinationSumService;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class CombinationSumApplication {
    private static final Logger log = Logger.getLogger(CombinationSumApplication.class.getName());

    public static void main(String[] args) {
        List<BigDecimal> denoms = List.of(
                new BigDecimal("2"), new BigDecimal("3"), new BigDecimal("5"));
        CombinationSumService service = new CombinationSumService();
        // Goal 8 for Rajesh SAV2001.
        log.info("Rajesh SAV2001 deposit combinations to reach 8: "
                + service.combinationsToGoal(denoms, new BigDecimal("8")));
    }
}
